func (p *Pool) Serve(ctx context.Context, req *Request) (*Reply, error) {
	if err := req.Validate(); err != nil {
		return nil, fmt.Errorf("invalid request: %w", err) // refuse immediately
	}
	conn, err := p.acquire(ctx)
	if err != nil {
		return nil, err // nothing held, nothing to release
	}
	defer p.release(conn)
	return conn.do(ctx, req)
}
